/* Shared runtime state, audio synthesis, toast notifications, cached scroll/viewport helpers, and lazy loader registry */

export const reduceMotionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
export let reduceMotion = reduceMotionQuery.matches;

export const motionChangeListeners = [];
export const notifyMotionChange = () => {
  motionChangeListeners.forEach((listener) => listener());
};

if (typeof reduceMotionQuery.addEventListener === "function") {
  reduceMotionQuery.addEventListener("change", (event) => {
    reduceMotion = event.matches;
    notifyMotionChange();
  });
}

export const finePointer = window.matchMedia("(hover: hover) and (pointer: fine)").matches;

export const readStore = (key) => {
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
};

export const writeStore = (key, value) => {
  try {
    window.localStorage.setItem(key, value);
  } catch {
    /* private mode */
  }
};

const motionButtons = Array.from(document.querySelectorAll("[data-motion-toggle]"));
let motionOff = readStore("motion") === "off";

export const applyMotion = (notify = true) => {
  const root = document.documentElement;
  if (motionOff) {
    if (root.dataset.motion !== "off") root.dataset.motion = "off";
  } else if (root.hasAttribute("data-motion")) {
    root.removeAttribute("data-motion");
  }
  const pressedStr = String(motionOff);
  const labelStr = motionOff ? "Turn motion back on" : "Turn motion off";
  motionButtons.forEach((button) => {
    if (button.getAttribute("aria-pressed") !== pressedStr) {
      button.setAttribute("aria-pressed", pressedStr);
    }
    if (button.textContent !== labelStr) {
      button.textContent = labelStr;
    }
  });
  if (notify) notifyMotionChange();
};

export const setMotionOff = (nextOff) => {
  motionOff = Boolean(nextOff);
  writeStore("motion", motionOff ? "off" : "on");
  applyMotion(true);
  return motionOff;
};

export const isMotionOff = () => motionOff;

export const toggleMotion = () => setMotionOff(!motionOff);

motionButtons.forEach((button) => {
  button.addEventListener("click", () => toggleMotion());
});
applyMotion(false);

export const stillPlaying = () => reduceMotion || motionOff;

export const text = (node) => (node?.textContent || "").replace(/\s+/g, " ").trim();
export const nodesOf = (selector, scope) => Array.from((scope || document).querySelectorAll(selector));

/* Cached document scroll limit updated lazily/on resize instead of eager synchronous boot read */
let cachedMaxScroll = 0;
export const refreshMaxScroll = () => {
  cachedMaxScroll = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
  return cachedMaxScroll;
};
export const invalidateMaxScroll = () => {
  cachedMaxScroll = 0;
};
export const getMaxScroll = () => (cachedMaxScroll > 0 ? cachedMaxScroll : refreshMaxScroll());

if ("ResizeObserver" in window && document.body) {
  let maxTimer = 0;
  new ResizeObserver(() => {
    window.clearTimeout(maxTimer);
    maxTimer = window.setTimeout(invalidateMaxScroll, 60);
  }).observe(document.body);
}
window.addEventListener("resize", invalidateMaxScroll, { passive: true });
window.addEventListener("load", invalidateMaxScroll, { once: true });

/* Hydrate deferred <picture>/<source>/<img> assets on intersection or navigation */
export const hydrateMedia = (root) => {
  if (!root) return;
  const sources = root.querySelectorAll ? root.querySelectorAll("source[data-srcset]") : [];
  sources.forEach((srcEl) => {
    srcEl.srcset = srcEl.dataset.srcset;
    srcEl.removeAttribute("data-srcset");
  });
  const imgs = root.querySelectorAll ? root.querySelectorAll("img[data-src], img[data-srcset]") : [];
  imgs.forEach((img) => {
    if (img.dataset.srcset) {
      img.srcset = img.dataset.srcset;
      img.removeAttribute("data-srcset");
    }
    if (img.dataset.src) {
      img.src = img.dataset.src;
      img.removeAttribute("data-src");
    }
    if (img.loading === "lazy") {
      img.loading = "eager";
    }
  });
};

let resolvePreloaderDone = null;
export const preloaderDone = new Promise((resolve) => {
  resolvePreloaderDone = resolve;
});
export { resolvePreloaderDone };

export const registry = {
  workDeck: null,
  workMascotState: null,
  onWorkMascotFrame: null,
  suppressWorkMascot: false,
  aboutExpand: null,
  expTheater: null,
  colophonDrawer: null,
  mascotSpeech: null,
  mascotGlance: () => {},
  mascotSection: () => {},
  mascotCheer: () => {},
  focusShell: null,
  loaders: {},
};

export const mascotGlance = (x, y) => registry.mascotGlance(x, y);
export const mascotSection = (id) => registry.mascotSection(id);
export const mascotCheer = (kind) => registry.mascotCheer(kind);
export const saySpeech = (msg, duration) => {
  if (registry.mascotSpeech) {
    registry.mascotSpeech.say(msg, duration);
  }
};

/* Tactile Audio Synthesizer (Web Audio API, 0 KB assets) */
export const AudioFX = (() => {
  let ctx = null;
  let enabled = false;

  const init = () => {
    if (!ctx) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (AudioContextClass) ctx = new AudioContextClass();
    }
    if (ctx && ctx.state === "suspended") {
      ctx.resume();
    }
  };

  const isEnabled = () => enabled;

  const setEnabled = (val) => {
    enabled = Boolean(val);
    writeStore("ma_sound_enabled", enabled ? "1" : "0");
    document.querySelectorAll("[data-sound-toggle]").forEach((btn) => {
      btn.setAttribute("aria-pressed", enabled ? "true" : "false");
      btn.classList.toggle("sound-toggle--active", enabled);
    });
    document.querySelectorAll("[data-hud-sound], [data-drawer-sound]").forEach((el) => {
      el.textContent = enabled ? "ON" : "OFF";
    });
    if (enabled) {
      init();
      chime();
    }
  };

  const click = () => {
    if (!enabled || !ctx) return;
    try {
      const t = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "triangle";
      osc.frequency.setValueAtTime(1400, t);
      osc.frequency.exponentialRampToValueAtTime(320, t + 0.012);
      gain.gain.setValueAtTime(0.04, t);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.012);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(t);
      osc.stop(t + 0.012);
    } catch {}
  };

  const tap = () => {
    if (!enabled || !ctx) return;
    try {
      const t = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(280, t);
      osc.frequency.exponentialRampToValueAtTime(80, t + 0.022);
      gain.gain.setValueAtTime(0.05, t);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.022);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(t);
      osc.stop(t + 0.022);
    } catch {}
  };

  const chime = () => {
    if (!enabled || !ctx) return;
    try {
      const t = ctx.currentTime;
      [587.33, 880].forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = "sine";
        osc.frequency.setValueAtTime(freq, t + i * 0.06);
        gain.gain.setValueAtTime(0.045, t + i * 0.06);
        gain.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.06 + 0.14);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(t + i * 0.06);
        osc.stop(t + i * 0.06 + 0.14);
      });
    } catch {}
  };

  try {
    if (localStorage.getItem("ma_sound_enabled") === "1") {
      enabled = true;
      document.addEventListener(
        "pointerdown",
        () => {
          if (enabled && !ctx) init();
        },
        { once: true }
      );
      document.querySelectorAll("[data-sound-toggle]").forEach((btn) => {
        btn.setAttribute("aria-pressed", "true");
        btn.classList.add("sound-toggle--active");
      });
      document.querySelectorAll("[data-hud-sound], [data-drawer-sound]").forEach((el) => {
        el.textContent = "ON";
      });
    }
  } catch {}

  document.querySelectorAll("[data-sound-toggle]").forEach((btn) => {
    btn.addEventListener("click", () => {
      init();
      setEnabled(!enabled);
    });
  });

  return { init, isEnabled, setEnabled, click, tap, chime };
})();

/* Sonner-Style Spring Toast Feedback */
export const Toast = {
  show(message, type = "info") {
    let container = document.getElementById("toast-container");
    if (!container) {
      container = document.createElement("div");
      container.id = "toast-container";
      container.className = "toast-container";
      container.setAttribute("aria-live", "polite");
      document.body.appendChild(container);
    }
    const toast = document.createElement("div");
    toast.className = `toast toast--${type}`;
    const iconEl = document.createElement("div");
    iconEl.className = "toast__icon";
    iconEl.setAttribute("aria-hidden", "true");
    iconEl.textContent = type === "success" ? "✓" : type === "error" ? "!" : "ℹ";
    const msgEl = document.createElement("div");
    msgEl.className = "toast__msg";
    msgEl.textContent = message;
    toast.append(iconEl, msgEl);
    container.appendChild(toast);
    AudioFX.chime();

    requestAnimationFrame(() => {
      toast.classList.add("toast--visible");
    });

    setTimeout(() => {
      toast.classList.remove("toast--visible");
      toast.classList.add("toast--exit");
      setTimeout(() => toast.remove(), 260);
    }, 3400);
  },
};

/* Shared Kicker decode animation */
const GLYPHS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/#—";
export const decode = (el) => {
  const final = el.dataset.text || el.textContent.trim();
  const chars = Array.from(final);
  const startedAt = performance.now();
  el.dataset.text = final;

  const step = (now) => {
    const progress = Math.min(1, (now - startedAt) / 560);
    const settled = Math.floor(progress * chars.length * 1.35);

    el.textContent = chars
      .map((char, index) => (char === " " || index < settled ? char : GLYPHS[(Math.random() * GLYPHS.length) | 0]))
      .join("");

    if (progress < 1) {
      window.requestAnimationFrame(step);
    } else {
      el.textContent = final;
    }
  };

  window.requestAnimationFrame(step);
};

/* Inertial Smooth Scroll */
export const canChildScroll = (target, deltaY) => {
  if (!(target instanceof Element)) return false;
  if (document.body.classList.contains("dialog-open") || target.closest("dialog[open]")) {
    return true;
  }
  let node = target;
  while (node && node !== document.body && node !== document.documentElement) {
    const style = window.getComputedStyle(node);
    const overflowY = style.overflowY;
    if (overflowY === "auto" || overflowY === "scroll" || overflowY === "overlay") {
      const maxScroll = node.scrollHeight - node.clientHeight;
      if (maxScroll > 1) {
        if (style.overscrollBehaviorY !== "auto") return true;
        if ((deltaY < 0 && node.scrollTop > 0) || (deltaY > 0 && node.scrollTop < maxScroll - 1)) {
          return true;
        }
      }
    }
    node = node.parentElement;
  }
  return false;
};

const finePointerScrollQuery = window.matchMedia("(any-pointer: fine)");

export const smoothScroller = (() => {
  const DURATION = 1.2;
  const WHEEL_MULTIPLIER = 0.85;
  const LINE_HEIGHT = 100 / 6;
  const EXPO_NORM = 1 - Math.pow(2, -10);
  const easeOutExpo = (t) => (t <= 0 ? 0 : t >= 1 ? 1 : (1 - Math.pow(2, -10 * t)) / EXPO_NORM);
  const clampScroll = (y) => Math.min(refreshMaxScroll(), Math.max(0, y));

  let enabled = false;
  let isRunning = false;
  let rafId = 0;
  let lastFrameTime = 0;
  let elapsed = 0;
  let fromY = 0;
  let currentY = 0;
  let targetY = 0;
  let lastWrittenY = 0;

  const stopAnimation = () => {
    if (rafId) {
      window.cancelAnimationFrame(rafId);
      rafId = 0;
    }
    isRunning = false;
    lastFrameTime = 0;
    registry.suppressWorkMascot = false;
  };

  const syncPosition = () => {
    currentY = window.scrollY;
    targetY = currentY;
    fromY = currentY;
    lastWrittenY = currentY;
    stopAnimation();
  };

  const step = (now) => {
    if (!enabled || !isRunning) {
      rafId = 0;
      return;
    }
    const dt = lastFrameTime ? Math.min(0.1, (now - lastFrameTime) / 1000) : 1 / 60;
    lastFrameTime = now;
    elapsed += dt;

    const progress = Math.min(1, elapsed / DURATION);
    const eased = easeOutExpo(progress);
    const nextY = fromY + (targetY - fromY) * eased;

    currentY = nextY;
    lastWrittenY = nextY;
    window.scrollTo({ top: nextY, left: window.scrollX, behavior: "instant" });

    if (progress >= 1 || Math.abs(targetY - nextY) < 0.35) {
      currentY = targetY;
      lastWrittenY = targetY;
      window.scrollTo({ top: targetY, left: window.scrollX, behavior: "instant" });
      stopAnimation();
      return;
    }

    rafId = window.requestAnimationFrame(step);
  };

  const animateTo = (nextTarget) => {
    const clamped = clampScroll(nextTarget);
    if (!enabled) {
      window.scrollTo({ top: clamped, left: window.scrollX, behavior: stillPlaying() ? "auto" : "smooth" });
      return;
    }
    if (!isRunning) {
      currentY = window.scrollY;
      lastWrittenY = currentY;
    }
    fromY = currentY;
    targetY = clamped;
    elapsed = 0;

    if (Math.abs(targetY - currentY) < 0.5) {
      syncPosition();
      return;
    }

    if (!isRunning) {
      isRunning = true;
      lastFrameTime = 0;
      rafId = window.requestAnimationFrame(step);
    }
  };

  const onWheel = (event) => {
    if (!enabled || event.ctrlKey || event.metaKey) return;
    if (canChildScroll(event.target, event.deltaY)) return;
    registry.suppressWorkMascot = false;

    let dy = event.deltaY;
    if (event.deltaMode === 1) dy *= LINE_HEIGHT;
    else if (event.deltaMode === 2) dy *= window.innerHeight;
    if (!dy) return;

    const max = getMaxScroll();
    if (registry.workDeck && registry.workDeck.isActive()) {
      registry.workDeck.handleSideWheel(event, dy);
    }
    if (registry.colophonDrawer && registry.colophonDrawer.handleWheel(event, max)) {
      return;
    }
    const base = isRunning ? targetY : window.scrollY;
    if (!isRunning && ((base <= 0 && dy < 0) || (base >= max && dy > 0))) {
      return;
    }

    event.preventDefault();
    animateTo(base + dy * WHEEL_MULTIPLIER);
  };

  const onScroll = () => {
    if (!enabled) return;
    if (!isRunning || Math.abs(window.scrollY - lastWrittenY) > 2) {
      syncPosition();
    }
  };

  const onKeyScroll = (event) => {
    if (!enabled) return;
    const scrollKeys = ["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End", " "];
    if (scrollKeys.includes(event.key)) {
      stopAnimation();
    }
  };

  const onPointerDown = (event) => {
    if (!enabled) return;
    if (event.clientX >= document.documentElement.clientWidth) {
      stopAnimation();
    }
  };

  const refreshState = () => {
    const shouldEnable = !stillPlaying() && finePointerScrollQuery.matches;
    if (shouldEnable === enabled) return;
    enabled = shouldEnable;
    if (document.documentElement.classList.contains("has-smooth-scroll") !== enabled) {
      document.documentElement.classList.toggle("has-smooth-scroll", enabled);
    }
    if (enabled) {
      window.addEventListener("wheel", onWheel, { passive: false });
      window.addEventListener("scroll", onScroll, { passive: true });
      window.addEventListener("keydown", onKeyScroll, { passive: true });
      window.addEventListener("pointerdown", onPointerDown, { passive: true });
    } else {
      stopAnimation();
      window.removeEventListener("wheel", onWheel);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("keydown", onKeyScroll);
      window.removeEventListener("pointerdown", onPointerDown);
    }
  };

  refreshState();
  motionChangeListeners.push(refreshState);
  if (typeof finePointerScrollQuery.addEventListener === "function") {
    finePointerScrollQuery.addEventListener("change", refreshState);
  }

  const shiftBy = (delta) => {
    if (!delta) return;
    const nextY = clampScroll(window.scrollY);
    currentY = nextY;
    fromY = nextY;
    targetY = clampScroll(targetY + delta);
    lastWrittenY = nextY;
  };

  const scrollToY = (y) => {
    const clamped = clampScroll(y);
    if (enabled) {
      animateTo(clamped);
    } else {
      window.scrollTo({ top: clamped, left: window.scrollX, behavior: stillPlaying() ? "auto" : "smooth" });
    }
  };

  const scrollToElement = (el, { focus = false } = {}) => {
    if (!el) return;
    hydrateMedia(el);
    const isWorkTarget = el.id === "work" || Boolean(el.closest && el.closest("#work"));
    const wd = registry.workDeck;
    const deckTargetY = wd && wd.isActive() ? wd.getCardScrollY(el) : null;
    if (deckTargetY !== null) {
      registry.suppressWorkMascot = false;
      scrollToY(deckTargetY);
      if (focus) {
        if (!el.hasAttribute("tabindex")) el.setAttribute("tabindex", "-1");
        el.focus({ preventScroll: true });
      }
      return;
    }
    registry.suppressWorkMascot = enabled && !isWorkTarget;
    const ae = registry.aboutExpand;
    if (el.id === "about" && ae && ae.isActive()) {
      scrollToY(ae.getStartY());
      if (focus) {
        if (!el.hasAttribute("tabindex")) el.setAttribute("tabindex", "-1");
        el.focus({ preventScroll: true });
      }
      return;
    }
    const et = registry.expTheater;
    if (el.id === "experience" && et && et.isActive()) {
      scrollToY(et.getStartY());
      if (focus) {
        if (!el.hasAttribute("tabindex")) el.setAttribute("tabindex", "-1");
        el.focus({ preventScroll: true });
      }
      return;
    }
    const pad = parseFloat(window.getComputedStyle(document.documentElement).scrollPaddingTop) || 0;
    const base = isRunning ? currentY : window.scrollY;
    const target = el.id === "top" ? 0 : el.getBoundingClientRect().top + base - pad;
    if (enabled) {
      animateTo(target);
    } else {
      el.scrollIntoView({ behavior: stillPlaying() ? "auto" : "smooth" });
    }
    if (focus) {
      if (!el.hasAttribute("tabindex")) el.setAttribute("tabindex", "-1");
      el.focus({ preventScroll: true });
    }
  };

  return { isEnabled: () => enabled, scrollToElement, scrollToY, shiftBy, sync: syncPosition };
})();

export const ensureForHash = async (hash) => {
  if (!hash || !hash.startsWith("#")) return;
  const id = hash.slice(1);
  if ((id === "work" || id.startsWith("project-")) && registry.loaders.workDeck) {
    await registry.loaders.workDeck();
  } else if (id === "experience" && registry.loaders.expTheater) {
    await registry.loaders.expTheater();
  } else if (id === "about" && registry.loaders.aboutToolkit) {
    await registry.loaders.aboutToolkit();
  } else if (id === "colophon" && registry.loaders.colophon) {
    await registry.loaders.colophon();
  } else if ((id === "systems" || id === "console") && registry.loaders.consoleShell) {
    await registry.loaders.consoleShell();
  } else if (id === "contact" && registry.loaders.contact) {
    await registry.loaders.contact();
  }
};

export const navigateToHash = async (hash, { focus = false } = {}) => {
  if (!hash || !hash.startsWith("#")) return false;
  const target = hash === "#" ? document.documentElement : document.getElementById(hash.slice(1));
  if (!target) return false;
  hydrateMedia(target);
  await ensureForHash(hash);

  if (hash === "#colophon" && registry.colophonDrawer) {
    registry.colophonDrawer.unlock({ instant: false, scrollTo: false });
  }
  const deckIntercept = Boolean(registry.workDeck && registry.workDeck.isActive() && registry.workDeck.getCardScrollY(target) !== null);
  const aboutIntercept = Boolean(registry.aboutExpand && registry.aboutExpand.isActive() && target.id === "about");
  const expIntercept = Boolean(registry.expTheater && registry.expTheater.isActive() && target.id === "experience");
  if (smoothScroller.isEnabled() || deckIntercept || aboutIntercept || expIntercept) {
    smoothScroller.scrollToElement(target, { focus });
    if (window.location.hash !== hash) {
      window.history.pushState(null, "", hash);
    }
    return true;
  }
  window.location.hash = hash;
  return true;
};
